Method.Source:
    /// <summary>
    /// Maps entity to datasource.
    /// </summary>
    /// <param name = "_entityCtx">Data entity runtime context.</param>
    /// <param name = "_dataSourceCtx">Data entity data source runtime context.</param>
    public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        this.skipDataSourceValidateField(fieldNum(METPurchParmTableEntity, ParmId), true);
        this.skipDataSourceValidateField(fieldNum(METPurchParmTableEntity, PurchId), true);
        
        super(_entityCtx, _dataSourceCtx);

        switch (_entityCtx.getDatabaseOperation())
        {
            case DataEntityDatabaseOperation::Insert:
                switch (_dataSourceCtx.name())
                {
                    case dataEntityDataSourceStr(METPurchParmTableEntity, PurchParmTable):
                        this.mapPurchParmTable(_dataSourceCtx);
                        break;
                }
                break;
        }
        
    }

    /// <summary>
    /// Maps entity to <c>PurchParmTable</c> datasource.
    /// </summary>
    /// <param name = "_dataSourceCtx">
    /// <c>DataEntityDataSourceRuntimeContext</c>.
    /// </param>
    private void mapPurchParmTable(DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        PurchParmTable purchParmTable;
        PurchTable     purchTable;
        boolean        isValid;
        str            errorMessage;

        purchParmTable = _dataSourceCtx.getBuffer();
        purchTable     = PurchTable::find(this.PurchId);

        [isValid, errorMessage] = this.validatePurchTable(purchTable);

        if (!isValid)
        {
            throw error(errorMessage);
        }

        purchParmTable.ParmId                = NumberSeq::newGetNum(CompanyInfo::numRefParmId()).num();
        purchParmTable.TransDate             = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        purchParmTable.ParmJobStatus         = ParmJobStatus::Waiting;
        purchParmTable.PurchName             = purchTable.PurchName;
        purchParmTable.DeliveryName          = purchTable.DeliveryName;
        purchParmTable.DeliveryPostalAddress = purchTable.DeliveryPostalAddress;
        purchParmTable.OrderAccount          = purchTable.OrderAccount;
        purchParmTable.CurrencyCode          = purchTable.CurrencyCode;
        purchParmTable.InvoiceAccount        = purchTable.InvoiceAccount;
        purchParmTable.Ordering              = DocumentStatus::PackingSlip;
        purchParmTable.TableRefId            = purchParmTable.ParmId;
        purchParmTable.METIsIntegration      = NoYes::Yes;
        purchParmTable.METIntegrationStatus  = METIntegrationStatus::ReadyToProcess;

        _dataSourceCtx.setBuffer(purchParmTable);
    }

    /// <summary>
    /// Validates purchTable.
    /// </summary>
    /// <param name = "_purchTable">
    /// <c>PurchTable</c>
    /// </param>
    /// <returns>Container containing valid check and error message.</returns>
    private container validatePurchTable(PurchTable _purchTable)
    {
        if (!_purchTable.RecId)
        {
            return [false, "@MET:PONotFound"];
        }

        if (_purchTable.DocumentState != VersioningDocumentState::Confirmed)
        {
            return [false, "@MET:PONotConfirmed"];
        }

        if (_purchTable.PurchStatus == PurchStatus::Received)
        {
            return [false, "@MET:POReceived"];
        }
        
        if (_purchTable.PurchStatus == PurchStatus::Invoiced)
        {
            return [false, "@MET:POInvoiced"];
        }

        return [true, ''];
    }
